  static void Autosave(string root)
  {
   var w=new MainWindow();Exception failure=null;var timer=new Timer{Interval=20};var watch=Stopwatch.StartNew();int phase=0;bool started=false;long now=0;MapData data=null;string path=null,before=null;int history=0,updates=0;var schedule=(AutoSaveSchedule)Get(w,"autoSchedule");schedule.Clock=()=>now;
   Action begin=()=>{data=Data("Auto "+phase);path=Path.Combine(root,"Auto "+phase+".hexmap");data.LoadedFileVersion=MainWindow.WriteProjectData(data,path,false);Call(w,"AdoptNewProject",data,path);Call(w,"ChangeOrientation","FlatTop");history=((System.Collections.ICollection)Get(w,"undo")).Count;updates=w.UiRefreshCount;before=File.ReadAllText(path);now=schedule.Due-1;Call(w,"PollAutoSave");Check(!(bool)Get(w,"autoSaving"),"Saved early");now=schedule.Due;
    Set(w,"gestureButton",MouseButtons.Left);Call(w,"PollAutoSave");Check(schedule.Pending&&!(bool)Get(w,"autoSaving"),"Gesture not deferred");Set(w,"gestureButton",MouseButtons.None);Set(w,"modalDepth",1);Call(w,"PollAutoSave");Check(schedule.Pending&&!(bool)Get(w,"autoSaving"),"Modal not deferred");Set(w,"modalDepth",0);
    var pending=Activator.CreateInstance(typeof(MainWindow).GetNestedType("PendingInkCommit",BindingFlags.NonPublic),true);Set(w,"pendingInk",pending);Call(w,"PollAutoSave");Check(!(bool)Get(w,"autoSaving"),"Eraser not deferred");((System.Threading.CancellationTokenSource)pending.GetType().GetField("Cancellation",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pending)).Dispose();Set(w,"pendingInk",null);
    if(phase==1)File.WriteAllText(path,"foreign version");if(phase==4)Set(w,"currentPath",Path.Combine(root,"missing","Auto.hexmap"));
    w.AutoPreparedForTest=()=>{var save=new object[]{Path.Combine(root,"must-not-save.hexmap"),false,null};Check(!(bool)Call(w,"TrySaveTo",save),"Manual save raced");var undo=new object[]{false,null};Check(!(bool)Call(w,"TryHistory",undo),"History raced");if(phase==2){Set(w,"map",Data("Other"));Set(w,"documentRevision",(long)Get(w,"documentRevision")+1);}if(phase==3)Call(w,"CancelAutoSave");};
    Call(w,"PollAutoSave");Check((bool)Get(w,"autoSaving"),"No scheduled job");started=true;watch.Restart();};
   w.Shown+=(s,e)=>w.BeginInvoke((Action)(()=>{try{begin();timer.Start();}catch(Exception ex){failure=ex;w.Dispose();}}));
   timer.Tick+=(s,e)=>{try{if(watch.ElapsedMilliseconds>15000)throw new Exception("Autosave timeout");if(!started||(bool)Get(w,"autoSaving"))return;started=false;Check(w.UiRefreshCount==updates,"Autosave refreshed entire UI");
    if(phase==0){Check(w.AutoSaveCount==1&&!(bool)Get(w,"dirty")&&MainWindow.ReadProjectData(path).Orientation=="FlatTop","Successful save/clean/roundtrip");Check(((System.Collections.ICollection)Get(w,"undo")).Count==history,"Autosave changed history");Check(schedule.Due==now+300000&&!schedule.Pending,"Clock not reset5min");Call(w,"PollAutoSave");Check(!(bool)Get(w,"autoSaving"),"Clean retry");}
    else{Check(w.AutoSaveError!=null,"Missing error info");if(phase==1){Check(schedule.Suspended&&File.ReadAllText(path)=="foreign version"&&(bool)Get(w,"dirty"),"Conflict overwritten/clean");now+=600000;Call(w,"PollAutoSave");Check(!(bool)Get(w,"autoSaving"),"Conflict not suspended");}else if(phase==2){Check(((MapData)Get(w,"map")).Name=="Other"&&File.ReadAllText(path)==before,"Stale save published");}else Check((bool)Get(w,"dirty")&&File.ReadAllText(path)==before,"Cancel/IO changed data");}
    Console.WriteLine("autosave phase="+phase+" success="+w.AutoSaveCount+" suspended="+schedule.Suspended+" error="+(w.AutoSaveError!=null));phase++;if(phase<5){begin();return;}timer.Stop();w.Dispose();
   }catch(Exception ex){failure=ex;timer.Stop();w.Dispose();}};Application.Run(w);timer.Dispose();if(failure!=null)throw failure;
   var original=Data("Snapshot");original.Cells[0].Gradient=GradientRules.Rainbow();var snapshot=ProjectSnapshot.Capture(original);original.Cells[0].Name="changed";original.Cells[0].Gradient.Stops[0].Color="#000000";Check(snapshot.Cells[0].Name!="changed"&&snapshot.Cells[0].Gradient.Stops[0].Color!="#000000","Mutable snapshot");
   Console.WriteLine("autosave PASS: controlled monotonic clock300000ms, deferred gesture/modal/eraser, single request, async exact shared writer, clean/Undo retention, conflict/IO/cancel/stale, manual routing guard, snapshot isolation; not real5min wait");
  }
