   original.Background=new MapBackground{Source=source,SourceId=source.Id,Opacity=45,Blur=2,Saturation=70};original.Cells[0].Fog=true;original.Cells[0].FogFill=new FillVariant{Gradient=GradientRules.Rainbow()};original.Ink.Add(new InkStroke{Gradient=GradientRules.Rainbow(),CycleWorld=300,Width=5,Points=new List<InkPoint>{new InkPoint(new PointF(10,10))}});
